   OneUi.gap(this,detail,12);LinearLayout times=OneUi.row(this);String[] labels={"모델 준비","분석","전체 처리"};long[] values={r.loadMs,r.inferenceMs,r.elapsedMs};for(int k=0;k<3;k++){LinearLayout box=OneUi.col(this);box.setPadding(Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,8));box.setBackground(Ui.round(this,Ui.BACK,8));box.addView(Ui.heading(this,values[k]+" ms",15));box.addView(OneUi.muted(this,labels[k],12));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,-2,1);if(k>0)bp.leftMargin=Ui.dp(this,8);times.addView(box,bp);}detail.addView(times,Ui.fill());
