 private String inputDescription(){String context=OneComparisonPolicy.groupLabel(group);if(selected==null)return context+" · 데모나 내 사진을 선택하세요";try{DemoStore.Item item=DemoStore.find(this,demoId);if(item!=null){String condition=OneDemoText.summary(item.difficulty,item.conditions);return context+" · "+item.title+(condition.isEmpty()?"":" · "+condition);}}catch(Exception ignored){}return context+" · 선택한 사진 · 같은 원본으로 비교";}
 private void selectModels(boolean recommended){if(current!=null||exporting||handoffBusy)return;Set<String> ids=new HashSet<>();for(OneModels.Entry entry:OneModels.list(this,feature,group))if(!recommended||entry.recommended)ids.add(entry.id);if(ids.isEmpty())ids.add(modelId);for(Map.Entry<String,CheckBox> entry:modelChecks.entrySet())entry.getValue().setChecked(ids.contains(entry.getKey()));updateActions();}
 private void pick(){if(exporting||handoffBusy)return;cancel("입력 변경");if(startGate!=null)startGate.cancel();try{startActivityForResult(OneInputs.picker(this,"image",feature).putExtra("group",group),PICK);}catch(ActivityNotFoundException e){Ui.error(this,"입력을 열 수 없습니다",e);}}
 @Override protected void onActivityResult(int code,int result,Intent data){
  super.onActivityResult(code,result,data);if(code!=PICK||result!=RESULT_OK||data==null)return;Uri uri=data.getData();if(uri==null){String text=data.getStringExtra("input_uri");if(text!=null)uri=Uri.parse(text);}if(uri==null||!"content".equals(uri.getScheme()))return;
  String nextDemo=data.getStringExtra("demo_id");if(nextDemo==null)nextDemo="";String nextGroup=inputGroup(nextDemo,data.getStringExtra("demo_group"));List<String> available=new ArrayList<>();for(OneModels.Entry entry:OneModels.list(this,feature,nextGroup))available.add(entry.id);
  String nextModel;try{nextModel=OneModelTestPolicy.modelAfterInput(modelId,OneModels.selected(this,feature,nextGroup),available,keepModel);}catch(IllegalArgumentException error){Ui.error(this,"시험할 모델을 다시 선택하세요",error);return;}
  List<String> previous=new ArrayList<>(selectedModels);selected=uri;completedSource=null;demoId=nextDemo;group=nextGroup;modelId=nextModel;selectedModels.clear();if(compareAll)selectedModels.addAll(OneModelTestPolicy.selectionAfterInput(available,previous));else selectedModels.add(modelId);
  if(startGate!=null)startGate.inputSelected(compareAll||keepModel);interrupted=false;restoredMetadata=false;runId="";inputSha="";recycle();reports.clear();build();if(active&&startGate!=null&&startGate.take())begin();
 }
 @Override protected void onResume(){super.onResume();active=true;updateActions();if(startGate!=null&&startGate.take())begin();}
 @Override protected void onPause(){active=false;imageExportCanceled.set(true);cancel("화면 이동");super.onPause();}
 @Override protected void onSaveInstanceState(Bundle s){if(selected!=null)s.putString("input",selected.toString());s.putFloat("scrollFraction",OneUi.scrollFraction(contentScroll));s.putString("group",group);s.putString("modelId",modelId);s.putBoolean("compareAll",compareAll);s.putBoolean("keepModel",keepModel);s.putString("demo",demoId);s.putString("runId",runId);s.putString("inputSha",inputSha);s.putBoolean("wasRunning",current!=null||interrupted);s.putParcelableArrayList("reports",new ArrayList<>(reports));s.putStringArrayList("selectedModels",new ArrayList<>(selectedModels));super.onSaveInstanceState(s);}
 private void begin(){if(current!=null||exporting||handoffBusy)return;if(selectedModels.isEmpty()){status.setText("비교할 모델을 선택하세요");return;}if(inputLabel!=null)inputLabel.setText(inputDescription());if(!active||selected==null){status.setText("데모나 사진을 선택하세요");return;}if(startGate!=null)startGate.cancel();interrupted=false;restoredMetadata=false;completedSource=null;recycle();reports.clear();share.setEnabled(false);save.setEnabled(false);cards.removeAllViews();Job job=new Job(selected,demoId);current=job;LATEST.set(job.id);run.setEnabled(false);status.setText("사진을 준비하고 있습니다");updateActions();try{worker.execute(job);}catch(RejectedExecutionException e){current=null;run.setEnabled(true);status.setText("화면을 다시 여세요");updateActions();}}
 private void cancel(String text){if(handoffBusy){OneImageHandoff.cancel(this);if(status!=null)status.setText(text);}Job job=current;if(job!=null){job.cancel();current=null;interrupted=true;if(status!=null)status.setText(text);}updateActions();}
 private boolean owns(Job job){return active&&!destroyed&&current==job&&!job.canceled.get()&&!isFinishing()&&!isDestroyed();}
 private void accept(Job job,List<OneModelRunner.Result> found,String sha,String error){if(!owns(job)){for(OneModelRunner.Result r:found)r.recycle();return;}current=null;run.setEnabled(true);inputSha=sha;runId=job.id;results.addAll(found);int ok=0;for(OneModelRunner.Result r:found)if("COMPLETED".equals(r.state))ok++;status.setText(error.isEmpty()?"분석 "+ok+" / "+found.size()+" 완료":"사진을 준비할 수 없습니다 · 다시 선택하세요");renderResults();completedSource=ok>0&&error.isEmpty()?job.input:null;updateActions();}
 private boolean hasCompleted(){for(OneModelRunner.Result value:results)if("COMPLETED".equals(value.state))return true;return false;}
 private static List<String[]> qualityRows(JSONObject metrics){List<String[]> rows=new ArrayList<>();JSONObject detection=metrics.optJSONObject("verifiedDetectionEvaluation");if(detection!=null)for(String key:new String[]{"TP","FP","FN","precision","recall","f1"}){String value=OneModelReport.qualityValue(key,detection.opt(key));if(!value.isEmpty())rows.add(new String[]{OneModelReport.qualityLabel(key)+" · 이 입력",value});}JSONObject task=metrics.optJSONObject("verifiedTaskEvaluation");if(task!=null&&task.optBoolean("referenceVerified")){Iterator<String> names=task.keys();while(names.hasNext()){String key=names.next();if("type".equals(key)||"referenceVerified".equals(key)||key.toLowerCase(Locale.ROOT).contains("sha"))continue;String value=OneModelReport.qualityValue(key,task.opt(key));if(!value.isEmpty()&&value.length()<160)rows.add(new String[]{OneModelReport.qualityLabel(key)+" · 이 입력",value});}}return rows;}
 private void updateActions(){if(run==null)return;boolean idle=active&&!destroyed&&current==null&&!exporting&&!handoffBusy;run.setEnabled(idle&&selected!=null&&!selectedModels.isEmpty());for(CheckBox box:modelChecks.values())box.setEnabled(idle);for(Button button:selectionButtons)button.setEnabled(idle);if(stopButton!=null)stopButton.setEnabled(current!=null);if(pickButton!=null)pickButton.setEnabled(active&&!destroyed&&!exporting&&!handoffBusy);save.setEnabled(idle&&!results.isEmpty()&&!restoredMetadata);share.setEnabled(idle&&!reports.isEmpty());for(Button image:imageButtons)image.setEnabled(idle);reuse.setEnabled(idle&&hasCompleted()&&selected!=null&&selected.equals(completedSource)&&inputSha.matches("[a-f0-9]{64}"));}
 private void reuse(){if(!active||destroyed||current!=null||exporting||handoffBusy||!hasCompleted()||selected==null||!selected.equals(completedSource))return;String previous=status.getText().toString();handoffBusy=true;status.setText("사진을 연결하고 있습니다");updateActions();OneImageHandoff.open(this,selected,inputSha,()->{handoffBusy=false;if(!destroyed){status.setText(previous);updateActions();}});}
 private final class Job implements Runnable {
  final String id=UUID.randomUUID().toString(),demo,jobGroup;final Uri input;final AtomicBoolean canceled=new AtomicBoolean();volatile InputStream stream;volatile boolean sourceOpened,sourceClosed;
  final List<String> modelIds;Job(Uri u,String d){input=u;demo=d;jobGroup=group;modelIds=new ArrayList<>(selectedModels);}
  void cancel(){canceled.set(true);InputStream owned=stream;if(owned!=null)try{owned.close();}catch(IOException ignored){}}
  public void run(){List<OneModelRunner.Result> found=new ArrayList<>();Bitmap image=null;String sha="",error="";try{ByteArrayOutputStream bytes=new ByteArrayOutputStream();InputStream in=getContentResolver().openInputStream(input);if(in==null)throw new IOException("input");sourceOpened=true;stream=in;try{if(canceled.get())throw new InterruptedIOException("canceled");byte[] block=new byte[16384];int n;while((n=in.read(block))!=-1){if(canceled.get())throw new InterruptedIOException("canceled");if(bytes.size()+n>32*1024*1024)throw new IOException("image size");bytes.write(block,0,n);}}finally{try{in.close();sourceClosed=true;}finally{stream=null;}}byte[] source=bytes.toByteArray();MessageDigest digest=MessageDigest.getInstance("SHA-256");StringBuilder hex=new StringBuilder();for(byte b:digest.digest(source))hex.append(String.format(Locale.ROOT,"%02x",b&255));sha=hex.toString();image=ImageIO.decode(source,1280);List<OneModels.Entry> entries=OneModels.list(getApplicationContext(),feature,jobGroup);for(OneModels.Entry entry:entries){if(canceled.get())break;if(!modelIds.contains(entry.id))continue;final String name=entry.title;runOnUiThread(()->{if(owns(this))status.setText(name+" 분석 중");});OneModelRunner.Result result=OneModelRunner.run(getApplicationContext(),feature,entry.id,image,canceled::get);OneDetectionTruth.apply(getApplicationContext(),demo,sha,result);found.add(result);try{OneRunLog.append(getApplicationContext(),result.json(sha,demo).put("group",jobGroup));}catch(Exception recordError){result.metrics.put("runLogWritten",false);}if(canceled.get())break;}}
   catch(Exception|LinkageError|OutOfMemoryError failure){error=failure.getClass().getSimpleName();}
   finally{if(image!=null)image.recycle();try{JSONArray values=new JSONArray();int successes=0,failures=0;for(OneModelRunner.Result r:found){values.put(r.json(sha,demo).put("group",jobGroup).put("detail",r.detail));if("COMPLETED".equals(r.state))successes++;else failures++;}if(LATEST.get().equals(id))Records.write(getApplicationContext(),"model-bench-result.json",new JSONObject().put("runId",id).put("feature",feature).put("group",jobGroup).put("inputSha256",sha).put("demoId",demo).put("state",canceled.get()?"CANCELED":!error.isEmpty()?"ERROR":failures>0?"PARTIAL_ERROR":"COMPLETED").put("successfulModels",successes).put("failedModels",failures).put("errorType",error).put("workerDone",true).put("sourceOpened",sourceOpened).put("sourceClosed",sourceOpened?sourceClosed:JSONObject.NULL).put("models",values));}catch(Exception ignored){}}
   final String actualSha=sha,problem=error;runOnUiThread(()->accept(this,found,actualSha,problem));
  }
 }
 private void shareImage(OneModelRunner.Result result){
  if(!active||destroyed||current!=null||exporting||handoffBusy||result.image==null||result.image.isRecycled())return;
  exporting=true;imageExportCanceled.set(false);updateActions();final Bitmap bitmap=result.image;final String sourceSha=inputSha,sourceModel=result.modelId,sourceDemo=demoId,exportId=UUID.randomUUID().toString();LATEST_IMAGE_EXPORT.set(exportId);
  try{worker.execute(()->{File target=null,pendingFile=null,creditedFile=null;String error="",imageSha="";OneInputAttribution.Entry attribution=OneInputAttribution.find(getApplicationContext(),sourceDemo,sourceSha);try{
   if(imageExportCanceled.get())throw new InterruptedIOException("Image export canceled");target=ImageIO.exported(getApplicationContext(),"AXSL-Vision-result-"+exportId+".png");pendingFile=new File(target.getPath()+".new");try(FileOutputStream out=new FileOutputStream(pendingFile)){if(!bitmap.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("PNG encode");out.getFD().sync();}
   if(imageExportCanceled.get())throw new InterruptedIOException("Image export canceled");Map<String,String> fields=attribution.png("AXSL Vision model output: "+sourceModel+"; encoded input SHA256 "+sourceSha);if(!fields.isEmpty()){creditedFile=new File(target.getPath()+".credited.new");try(InputStream in=new FileInputStream(pendingFile);FileOutputStream out=new FileOutputStream(creditedFile)){OnePngAttribution.copy(in,out,fields,imageExportCanceled::get);out.getFD().sync();}if(!creditedFile.renameTo(pendingFile))throw new IOException("PNG credit commit");}
   MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream input=new FileInputStream(pendingFile)){byte[] block=new byte[16384];int n;while((n=input.read(block))!=-1){if(imageExportCanceled.get())throw new InterruptedIOException("Image export canceled");digest.update(block,0,n);}}StringBuilder hex=new StringBuilder();for(byte value:digest.digest())hex.append(String.format(Locale.ROOT,"%02x",value&255));imageSha=hex.toString();if(imageExportCanceled.get()||!pendingFile.renameTo(target))throw new IOException("Image commit canceled");
  }catch(Exception|LinkageError|OutOfMemoryError e){error=e.getClass().getSimpleName();}finally{if(pendingFile!=null&&pendingFile.exists())pendingFile.delete();if(creditedFile!=null&&creditedFile.exists())creditedFile.delete();}
  File file=target;String failure=error,outputSha=imageSha;runOnUiThread(()->{exporting=false;if(destroyed||!active||imageExportCanceled.get()){if(file!=null)file.delete();imageExportRecord(exportId,"CANCELED",sourceModel,sourceSha,outputSha,null,attribution);if(destroyed)recycle();else updateActions();return;}updateActions();if(!failure.isEmpty()||file==null||!file.isFile()){imageExportRecord(exportId,"ERROR",sourceModel,sourceSha,outputSha,null,attribution);status.setText("결과 이미지를 만들 수 없습니다");return;}
   try{imageExportRecord(exportId,"SAVED",sourceModel,sourceSha,outputSha,file,attribution);Uri uri=ImageIO.uri(getApplicationContext(),file);Intent share=new Intent(Intent.ACTION_SEND).setType("image/png").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(!attribution.text().isEmpty())share.putExtra(Intent.EXTRA_TEXT,attribution.text());share.setClipData(ClipData.newRawUri("AXSL Vision 결과 이미지",uri));startActivity(Intent.createChooser(share,"결과 이미지 공유"));}catch(Exception e){status.setText("결과 이미지를 공유할 수 없습니다");}
  });});}catch(RejectedExecutionException e){exporting=false;updateActions();}
 }
 private void imageExportRecord(String id,String state,String model,String sourceSha,String outputSha,File file,OneInputAttribution.Entry attribution){if(!LATEST_IMAGE_EXPORT.get().equals(id))return;try{JSONObject record=new JSONObject().put("exportId",id).put("state",state).put("feature",feature).put("group",group).put("modelId",model).put("sourceInputSha256",sourceSha).put("outputSha256",outputSha).put("file",file==null?"":"exports/"+file.getName()).put("mime","image/png").put("originalInputReplaced",false).put("dataAttribution",attribution.json()).put("pngAttributionEmbedded",file!=null&&!attribution.empty());if(file!=null){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),bounds);record.put("width",bounds.outWidth).put("height",bounds.outHeight);}Records.write(getApplicationContext(),"image-export-result.json",record);}catch(Exception ignored){}}
 private void export(){
  if(results.isEmpty()||restoredMetadata||current!=null||exporting||handoffBusy)return;exporting=true;updateActions();final List<OneModelRunner.Result> snapshot=new ArrayList<>(results);final String sha=inputSha,id=runId,demo=demoId,resultGroup=group;
  try{worker.execute(()->{ArrayList<Uri> uris=new ArrayList<>();String error="";try{
   OneInputAttribution.Entry attribution=OneInputAttribution.find(getApplicationContext(),demo,sha);JSONArray rows=new JSONArray();StringBuilder csv=new StringBuilder("\uFEFFfeature,model,state,inputSha256,modelSha256,loadMs,inferenceMs,elapsedMs,summary,detail,metricsJson,attribution,group\r\n");List<OneModelReport.Model> cards=new ArrayList<>();
   for(OneModelRunner.Result r:snapshot){rows.put(r.json(sha,demo).put("group",resultGroup).put("detail",r.detail));csv.append(OneModelMath.csv(r.feature)).append(',').append(OneModelMath.csv(r.modelId)).append(',').append(OneModelMath.csv(r.state)).append(',').append(OneModelMath.csv(sha)).append(',').append(OneModelMath.csv(r.modelSha256)).append(',').append(r.loadMs).append(',').append(r.inferenceMs).append(',').append(r.elapsedMs).append(',').append(OneModelMath.csv(r.summary)).append(',').append(OneModelMath.csv(r.detail)).append(',').append(OneModelMath.csv(r.metrics.toString())).append(',').append(OneModelMath.csv(attribution.text())).append(',').append(OneModelMath.csv(resultGroup)).append("\r\n");
    OneModelReport.Model card=new OneModelReport.Model();card.title=OneModels.title(getApplicationContext(),feature,r.modelId);card.state=r.state;card.summary=r.summary;card.detail=r.detail;card.modelSha=r.modelSha256;card.loadMs=r.loadMs;card.inferenceMs=r.inferenceMs;card.elapsedMs=r.elapsedMs;
    if(r.image!=null&&!r.image.isRecycled()){int width=Math.min(960,r.image.getWidth());Bitmap small=Bitmap.createScaledBitmap(r.image,width,Math.max(1,(int)(r.image.getHeight()*(width/(double)r.image.getWidth()))),true);ByteArrayOutputStream bytes=new ByteArrayOutputStream();boolean png="studio".equals(feature);small.compress(png?Bitmap.CompressFormat.PNG:Bitmap.CompressFormat.JPEG,png?100:84,bytes);if(small!=r.image)small.recycle();card.image=(png?"data:image/png;base64,":"data:image/jpeg;base64,")+android.util.Base64.encodeToString(bytes.toByteArray(),android.util.Base64.NO_WRAP);}
    card.metrics.addAll(qualityRows(r.metrics));
    cards.add(card);
   }
   String logo="";
   OneCatalog.Feature task=OneCatalog.find(feature);String demoTitle=demo;DemoStore.Item sample=DemoStore.find(getApplicationContext(),demo);if(sample!=null){demoTitle=sample.title;String conditions=OneDemoText.summary(sample.difficulty,sample.conditions);if(!conditions.isEmpty())demoTitle+=" · "+conditions;}String html=OneModelReport.html(task==null?feature:task.title,demoTitle+" · "+OneComparisonPolicy.groupLabel(resultGroup),sha,cards,logo,attribution.text());JSONObject report=new JSONObject().put("application",getPackageName()).put("runId",id).put("feature",feature).put("demoId",demo).put("group",resultGroup).put("inputSha256",sha).put("models",rows).put("dataAttribution",attribution.json()).put("exportedAt",System.currentTimeMillis());
   for(String ext:new String[]{"html","csv","json"}){File file=ImageIO.exported(getApplicationContext(),"AXSL-Vision-models-"+id+"."+ext),pendingFile=new File(file.getPath()+".new");byte[] data=(ext.equals("html")?html:ext.equals("csv")?csv.toString():report.toString(2)).getBytes(StandardCharsets.UTF_8);try(FileOutputStream stream=new FileOutputStream(pendingFile)){stream.write(data);stream.getFD().sync();}if(!pendingFile.renameTo(file))throw new IOException("report commit");uris.add(ImageIO.uri(getApplicationContext(),file));}
   List<String> executedModels=new ArrayList<>();for(OneModelRunner.Result result:snapshot)executedModels.add(result.modelId);for(OneReportBindings.Binding binding:OneReportBindings.savedModels(executedModels,"exports/AXSL-Vision-models-"+id+".html"))OneRunLog.append(getApplicationContext(),new JSONObject().put("type","model-report").put("feature",feature).put("group",resultGroup).put("modelId",binding.modelId).put("inputSha256",sha).put("demoId",demo).put("state",binding.state).put("createdAt",System.currentTimeMillis()).put("summary","모델 "+snapshot.size()+"개 · HTML · CSV · JSON 리포트").put("reportPath",binding.reportPath));
  }catch(Exception|LinkageError failure){error=failure.getClass().getSimpleName();}final String problem=error;runOnUiThread(()->{exporting=false;if(destroyed){recycle();return;}updateActions();if(!problem.isEmpty()){status.setText("리포트를 저장할 수 없습니다 · "+problem);return;}reports.clear();reports.addAll(uris);updateActions();status.setText("HTML · CSV · JSON 리포트 저장 완료");});});}catch(RejectedExecutionException error){exporting=false;updateActions();}
 }
 private void share(){if(reports.isEmpty()||current!=null||exporting||handoffBusy)return;Intent intent=new Intent(Intent.ACTION_SEND_MULTIPLE).setType("*/*").putParcelableArrayListExtra(Intent.EXTRA_STREAM,new ArrayList<>(reports)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);ClipData clip=ClipData.newRawUri("AXSL Vision 모델 리포트",reports.get(0));for(int n=1;n<reports.size();n++)clip.addItem(new ClipData.Item(reports.get(n)));intent.setClipData(clip);try{startActivity(Intent.createChooser(intent,"모델 리포트 공유"));}catch(ActivityNotFoundException e){Ui.error(this,"공유 앱을 열 수 없습니다",e);}}
 private void recycle(){for(OneModelRunner.Result r:results)r.recycle();results.clear();}
 @Override protected void onDestroy(){destroyed=true;cancel("화면 닫기");worker.shutdown();if(!exporting&&!resultsRetained)recycle();super.onDestroy();}
